create table if not exists public.tech_logs (
  id bigint generated by default as identity primary key, boutique_id text not null references public.boutiques(id) on delete cascade, user_id uuid null, level text not null check (level in ('error','warn','info')), category text not null check (category in ('rpc','loading','sync','printing','network','session','other')), message text not null, detail text null, context jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);
create index if not exists tech_logs_boutique_created_idx on public.tech_logs(boutique_id,created_at desc);
alter table public.tech_logs enable row level security; revoke all on public.tech_logs from public, anon, authenticated;
create or replace function public.record_tech_log(p_boutique_id text,p_level text,p_category text,p_message text,p_detail text default null,p_context jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path='pg_catalog','public','private' as $$ declare v_id bigint; begin if auth.uid() is null or not private.auth_has_boutique_access(p_boutique_id) then raise exception 'forbidden'; end if; if p_level not in ('error','warn','info') or p_category not in ('rpc','loading','sync','printing','network','session','other') then raise exception 'invalid tech log'; end if; insert into public.tech_logs(boutique_id,user_id,level,category,message,detail,context) values(p_boutique_id,auth.uid(),p_level,p_category,left(p_message,500),left(p_detail,4000),coalesce(p_context,'{}'::jsonb)) returning id into v_id; return v_id; end $$;
revoke all on function public.record_tech_log(text,text,text,text,text,jsonb) from public,anon; grant execute on function public.record_tech_log(text,text,text,text,text,jsonb) to authenticated;
create or replace function public.get_tech_logs(p_boutique_id text,p_limit integer default 200) returns table(id bigint,user_id uuid,level text,category text,message text,detail text,context jsonb,created_at timestamptz) language plpgsql stable security definer set search_path='pg_catalog','public','private' as $$ begin if auth.uid() is null or not (private.auth_is_super_admin() or exists(select 1 from public.boutique_assignments a where a.boutique_id=p_boutique_id and a.user_id=auth.uid() and a.role='owner')) then raise exception 'forbidden'; end if; return query select t.id,t.user_id,t.level,t.category,t.message,t.detail,t.context,t.created_at from public.tech_logs t where t.boutique_id=p_boutique_id order by t.created_at desc limit greatest(1,least(coalesce(p_limit,200),500)); end $$;
revoke all on function public.get_tech_logs(text,integer) from public,anon; grant execute on function public.get_tech_logs(text,integer) to authenticated;
